# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SİVAS KONGRESİ (4 - 11 EYLÜL 1919) VE TEMEL KARARLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kongrenin Niteliği ve Engellemeler</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Toplanış ve Kararlar Bakımından: ULUSAL (MİLLÎ)</text>\n  <text x="180" y="118" text-anchor="middle" font-size="11" fill="#334155">• Engelleme Girişimleri:</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" fill="#334155">1. Elazığ Valisi Ali Galip Olayı (Damat Ferit emriyle)</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" fill="#334155">2. Fransız subayı Binbaşı Bruno\'nun işgal tehdidi</text>\n  <text x="180" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Kongre Başkanlığı Sorunu:</text>\n  <text x="180" y="196" text-anchor="middle" font-size="11" fill="#334155">Mustafa Kemal Paşa oy çoğunluğuyla başkan seçildi.</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">• Yayın Organı: İrade-i Milliye Gazetesi çıkarıldı.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sivas Kongresi\'nin Tarihî Kararları</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">1. Manda ve Himaye KESİN OLARAK Reddedildi:</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">"Ya istiklal ya ölüm!" parolasıyla tam bağımsızlık.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">2. Millî Cemiyetler Tek Çatı Altında Birleştirildi:</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">"Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti"</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">3. Temsil Heyeti Ulusallaştırıldı (16 Üye):</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">"Temsil Heyeti bütün vatanı temsil eder." Batı Cephesi</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#334155">komutanlığına Ali Fuat Paşa atandı (Yürütme yetkisi!).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AMASYA GÖRÜŞMELERİ (20 - 22 EKİM 1919) VE SİYASİ SONUÇLARI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">İlk Siyasi Başarı: Damat Ferit\'in İstifası</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" fill="#334155">• Kongreyi engellemeye çalışan Damat Ferit Paşa</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#334155">Hükûmeti ile Anadolu\'nun haberleşmesi kesildi.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">• Sonuç: Damat Ferit Paşa istifa etti (30 Eylül 1919)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">(Temsil Heyeti\'nin İstanbul\'a karşı ilk siyasi zaferi!)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#334155">• Yeni kurulan Ali Rıza Paşa Hükûmeti, Bahriye Nazırı</text>\n  <text x="180" y="200" text-anchor="middle" font-size="11" fill="#334155">Salih Paşa\'yı Amasya\'ya görüşmeye gönderdi.</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">Taraflar: Mustafa Kemal Paşa ⇄ Bahriye Nazırı Salih Paşa</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Amasya Görüşmeleri Kararları ve Önemi</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">• Önemi: İstanbul Hükûmeti, Temsil Heyeti\'nin</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">hukuki ve siyasi varlığını RESMEN TANIDI!</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#334155">• Vatanın bütünlüğü ve bağımsızlığı korunacaktır.</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11" fill="#334155">• Azınlıklara siyasi egemenliği bozacak hak verilmeyecek.</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">• Mebusan Meclisi derhâl açılacak ve seçimler yapılacak.</text>\n  <text x="520" y="200" text-anchor="middle" font-size="11" fill="#be123c">Not: İstanbul Hükûmeti otoritesi sarsılacağı için meclisin</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#be123c">İstanbul dışında (Anadolu\'da) toplanmasını kabul etmedi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TEMSİL HEYETİ\'NİN ANKARA\'YA GELİŞİ (27 ARALIK 1919) VE NEDENLERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Ankara\'nın Merkez Seçilme Nedenleri</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">1. Coğrafi Konum ve Güvenlik:</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#334155">Anadolu\'nun ortasında, işgalden uzak güvenli bir yer.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">2. Ulaşım ve Haberleşme Ağı:</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#334155">Demir yolu ve telgraf ağıyla İstanbul\'a ve cephelere bağlı.</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">3. Batı Cephesi\'ne ve İstanbul\'a Yakınlık:</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#334155">Yunan işgalindeki Batı Cephesi\'ne ve Mebusan Meclisi</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">çalışmalarını yakından izlemek için İstanbul\'a yakın.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Askerî-Halk Desteği ve Millî Basın</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">4. Askerî Güç ve Halkın Vatanseverliği:</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">Ali Fuat Paşa komutasındaki 20. Kolordu\'nun Ankara\'da</text>\n  <text x="520" y="132" text-anchor="middle" font-size="11" fill="#334155">bulunması ve Ankara halkının (Seymenlerin) tam desteği.</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Millî Mücadele Dönemi Basın Yayın Organları:</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#334155">1. İrade-i Milliye (Sivas Kongresi\'nde çıkarıldı)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#334155">2. Hâkimiyet-i Milliye (Ankara\'da 10 Ocak 1920\'de çıktı)</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#881337">3. Anadolu Ajansı (6 Nisan 1920 — Doğru haber kaynağı)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
